*{box-sizing:border-box} :root{--ink:#17211d;--muted:#75817b;--green:#253a32;--green2:#426353;--gold:#c0924c;--paper:#f5f4ef;--line:#e6e5de;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'Playfair Display',serif}html,body{margin:0;width:100%;height:100%;font-family:var(--sans);color:var(--ink);background:#f5f4ef}body{overflow:hidden}.game-shell{height:100dvh;min-height:600px;max-width:1800px;margin:auto;background:var(--paper);overflow:hidden}.topbar{height:68px;padding:0 32px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);background:#faf9f5;position:relative;z-index:5}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);font-weight:800;font-size:12px;letter-spacing:1.55px;line-height:1.1}.brand-mark{font-size:27px;color:var(--gold)}.brand small{display:block;color:#9a9c92;font:9px var(--mono);letter-spacing:1.4px;margin-top:5px}.day-block{display:flex;align-items:center;gap:10px;font:10px var(--mono);letter-spacing:1px;color:#737b72}.live-dot{height:7px;width:7px;background:#7d9a74;border-radius:50%;box-shadow:0 0 0 3px #7d9a741c}.weather{border-left:1px solid var(--line);padding-left:14px;margin-left:4px;color:#9a8b6c}.top-actions{display:flex;align-items:center;gap:14px}.icon-btn,.menu-btn{background:none;border:0;color:var(--green);font:12px var(--mono);cursor:pointer}.icon-btn{font-size:17px;width:34px;height:34px}.menu-btn span{font-size:15px;margin-left:7px}.game-layout{display:grid;grid-template-columns:270px minmax(350px,1fr) 350px;height:calc(100% - 68px)}.left-panel,.right-panel{padding:27px 24px 20px;overflow:auto;scrollbar-width:thin;scrollbar-color:#d6d5cd transparent}.left-panel{border-right:1px solid var(--line);background:#f8f7f2}.eyebrow{font:9px var(--mono);letter-spacing:1.4px;color:#8c9288}.left-panel h1{font:600 36px/.99 var(--serif);letter-spacing:-.7px;margin:12px 0 9px}.left-panel h1 em{color:var(--green2);font-weight:600}.intro{font-size:11px;color:#858b83;margin:0 0 20px}.leader-card{height:54px;background:#eeeee7;display:flex;align-items:center;gap:10px;padding:7px 10px}.avatar{height:35px;width:35px;background:#30473d;color:#e3c18a;border-radius:50%;display:grid;place-items:center;font:18px var(--serif)}.leader-card strong{display:block;font-size:10px}.leader-card small{display:block;color:#888f85;font-size:9px;margin-top:4px}.rank{color:var(--gold);margin-left:auto;font-size:17px}.stat-list{padding:12px 0 9px}.stat-row{height:31px;display:flex;align-items:center;gap:8px}.stat-icon{width:17px;font-size:13px;text-align:center}.cash{color:#638265}.rep{color:#bf9855}.heat{color:#b37564}.stat-name{font:9px var(--mono);letter-spacing:.6px;color:#91958c}.stat-row b{margin-left:auto;font:11px var(--mono);color:#293a31}.stat-row b small{font-size:9px;color:#9a9e95}.heat-track{height:3px;background:#e6e4dc}.heat-track>div{height:100%;width:12%;background:#c08068;transition:width .4s}.heat-caption{display:flex;justify-content:space-between;font:7px var(--mono);color:#a6a69e;margin-top:6px;letter-spacing:.45px}.section-rule{height:1px;background:var(--line);margin:18px 0 14px}.district-heading,.feed-head{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.7px;color:#828a80}.district-heading span+span{color:#b19a70}.district-list{margin-top:8px}.district-item{width:100%;height:39px;border:0;border-bottom:1px solid #eeede7;display:flex;align-items:center;gap:8px;background:transparent;text-align:left;padding:0 3px;cursor:pointer;color:#59635c}.district-item:hover,.district-item.active{color:var(--green);background:#f0f0e9}.district-symbol{font-size:12px;color:#9b9f91;width:14px}.district-item.owned .district-symbol{color:#688267}.district-item.rival .district-symbol{color:#bf806d}.district-item b{font-size:10px;font-weight:600}.district-item small{margin-left:auto;font:8px var(--mono);color:#a0a399}.sidebar-note{margin-top:19px;border-left:2px solid #c6a567;padding:5px 0 5px 10px;font:italic 10px/1.5 var(--serif);color:#81877c}.sidebar-note span{color:var(--gold);font-style:normal;margin-right:3px}.map-stage{background:#d6d9ce;position:relative;overflow:hidden;isolation:isolate}#cityCanvas{display:block;width:100%;height:100%;touch-action:none;cursor:grab}#cityCanvas:active{cursor:grabbing}.map-vignette{position:absolute;inset:0;pointer-events:none;z-index:1;box-shadow:inset 0 0 100px #27372b24}.map-label{z-index:2;position:absolute;top:24px;left:25px;background:#f8f7f0e8;padding:9px 13px 8px;box-shadow:0 2px 12px #33433115;font:10px var(--mono);letter-spacing:.9px;color:#344a3c}.map-label small{display:block;font-size:7px;letter-spacing:1px;color:#93988b;margin:4px 0 0 17px}.map-pin{color:#b8995b;margin-right:7px;font-size:15px}.map-tools{position:absolute;top:22px;right:20px;z-index:2;background:#faf9f1e8;display:flex;align-items:center;height:32px;box-shadow:0 2px 10px #33433118}.map-tools button{border:0;background:transparent;color:#56665b;width:31px;height:32px;font-size:18px;cursor:pointer}.map-tools button:hover{background:#e8e9df}.map-tools span{font:9px var(--mono);color:#787f73;padding:0 3px}.map-tools i{height:17px;border-left:1px solid #deded5;margin:0 3px}.map-legend{position:absolute;left:22px;bottom:20px;z-index:2;display:flex;gap:13px;background:#faf9f0e8;padding:9px 11px;font:7px var(--mono);letter-spacing:.5px;color:#7e877d}.map-legend span{display:flex;align-items:center;gap:5px}.map-legend i{width:7px;height:7px;display:inline-block;background:#6c8b72}.map-legend .legend-open{background:#f4f0e2;border:1px solid #b8b5a7}.map-legend .legend-rival{background:#bd7768}.district-card{position:absolute;z-index:3;left:50%;bottom:58px;transform:translate(-50%,15px);width:min(360px,calc(100% - 36px));padding:18px 19px 16px;background:#faf9f2f4;box-shadow:0 10px 35px #27372b26;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s}.district-card.show{opacity:1;transform:translate(-50%,0);pointer-events:auto}.close-card{position:absolute;right:12px;top:9px;border:0;background:none;color:#899087;font-size:21px;cursor:pointer}.card-overline{font:8px var(--mono);letter-spacing:.8px;color:#90958b}.card-overline span{float:right;color:#638067}.district-card h2{font:600 25px var(--serif);margin:7px 0 4px;color:#293d32}.district-card>p{margin:0;color:#83897f;font-size:10px}.district-facts{display:flex;border-top:1px solid #e8e7df;border-bottom:1px solid #e8e7df;padding:11px 0;margin:13px 0}.district-facts>div{flex:1;border-right:1px solid #e8e7df;padding-left:9px}.district-facts>div:first-child{padding-left:0}.district-facts>div:last-child{border:0}.district-facts small{display:block;font:7px var(--mono);letter-spacing:.2px;color:#969a90}.district-facts b{display:block;font:11px var(--mono);color:#384c3f;margin-top:5px}.claim-btn{width:100%;height:36px;border:0;background:#304a3b;color:#f8f7ed;font:9px var(--mono);letter-spacing:.8px;text-align:left;padding:0 13px;cursor:pointer}.claim-btn span{float:right;font-size:15px}.claim-btn:hover{background:#426352}.claim-btn:disabled{background:#777d72;cursor:default}.map-hint{position:absolute;bottom:23px;right:21px;z-index:2;color:#56655799;font:8px var(--mono);letter-spacing:.6px;transition:opacity .2s}.map-hint span{font-size:13px;margin-left:4px}.right-panel{background:#fbfaf6;border-left:1px solid var(--line);padding:27px 24px 18px}.right-title{display:flex;align-items:flex-end;justify-content:space-between}.right-title h2{font:600 24px var(--serif);margin:7px 0 0;letter-spacing:-.4px}.turn-mark{font:30px var(--serif);color:#ded9cc}.right-copy{font-size:10px;line-height:1.6;color:#858b83;margin:9px 0 17px;max-width:275px}.action-list{display:grid;gap:7px}.action-card{width:100%;height:56px;padding:7px 9px;display:flex;align-items:center;gap:9px;text-align:left;background:#f5f4ee;border:1px solid #eeede6;cursor:pointer;color:var(--ink);transition:background .15s,transform .15s}.action-card:hover{background:#eeeeE6;transform:translateX(-2px)}.action-icon{width:33px;height:33px;display:grid;place-items:center;background:#e3e9df;color:#59745b;font-size:18px}.action-icon.business{background:#ebe7d9;color:#a08956}.action-icon.network{background:#e7e3eb;color:#77688e}.action-icon.laylow{background:#e3e8e7;color:#627a7b}.action-text{display:block;min-width:0}.action-text b{display:block;font-size:10px;font-weight:700}.action-text small{display:block;margin-top:4px;color:#92968d;font-size:8px;white-space:nowrap}.action-cost{margin-left:auto;white-space:nowrap;color:#85927d;font:8px var(--mono)}.action-arrow{color:#a7a89d;font-size:14px;margin-left:1px}.next-turn{margin-top:16px;background:#31483a;padding:11px 10px;display:flex;justify-content:space-between;align-items:center;color:#f5f3e9}.next-turn>div{display:flex;align-items:center;gap:8px}.next-icon{font-size:19px;color:#c5ab76}.next-turn b{display:block;font:8px var(--mono);letter-spacing:.5px}.next-turn small{display:block;color:#bdc5b9;font-size:8px;margin-top:4px}.next-turn button{border:1px solid #ffffff47;background:#ffffff0b;color:#f9f8ef;height:29px;padding:0 10px;font:8px var(--mono);letter-spacing:.4px;cursor:pointer;white-space:nowrap}.next-turn button:hover{background:#ffffff1a}.next-turn button span{font-size:13px;margin-left:4px}.feed-head{margin:20px 0 9px;font-size:8px}.feed-head i{flex:1;border-top:1px solid var(--line);margin:0 8px}.event-feed{max-height:160px;overflow:auto}.feed-event{display:flex;gap:9px;padding:8px 0;border-bottom:1px solid #efeee8}.feed-dot{width:7px;height:7px;border-radius:50%;margin:4px 0 0 2px;flex-shrink:0;background:#799477}.feed-dot.gold{background:#c09b5f}.feed-dot.alert{background:#bd7967}.feed-event b{font-size:9px;font-weight:700}.feed-event p{font-size:9px;line-height:1.4;color:#858b82;margin:3px 0}.feed-event small{font:7px var(--mono);color:#afb0a5}.objective{margin-top:14px;padding:11px;background:#f1f0e9;display:flex;gap:9px}.objective>span{color:#b79455;font-size:15px}.objective b{font:8px var(--mono);letter-spacing:.5px;color:#637064}.objective p{font-size:9px;color:#858c82;line-height:1.4;margin:4px 0 8px}.objective-track{height:3px;background:#deded4}.objective-track i{height:100%;display:block;background:#81927b;width:25%;transition:width .3s}.objective small{display:block;text-align:right;font:7px var(--mono);color:#979c92;margin-top:5px}.mobile-nav{display:none}.toast{position:fixed;z-index:10;bottom:24px;left:50%;transform:translate(-50%,15px);background:#263c31;color:#f7f5ea;padding:11px 18px;font:10px var(--mono);letter-spacing:.2px;box-shadow:0 7px 24px #17261d38;opacity:0;pointer-events:none;transition:.25s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;z-index:20;inset:0;display:grid;place-items:center;background:#15201983;opacity:0;pointer-events:none;transition:opacity .2s;padding:18px}.modal-backdrop.show{opacity:1;pointer-events:auto}.modal{position:relative;width:min(460px,100%);background:#faf9f3;padding:30px;box-shadow:0 18px 55px #10191350}.close-modal{position:absolute;right:17px;top:13px;background:none;border:0;font-size:23px;color:#888;cursor:pointer}.modal h2{font:600 31px var(--serif);margin:8px 0 18px}.modal-content{border-top:1px solid var(--line);padding-top:14px}.ledger-row{display:flex;justify-content:space-between;border-bottom:1px solid #eeede7;padding:11px 0;font-size:11px}.ledger-row small{font:9px var(--mono);color:#858c82}.ledger-row b{font:11px var(--mono);color:#405a47}.modal-tip{font-size:10px;color:#7b847a;line-height:1.6;margin:15px 0 0}.crew-person{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #eeede7}.crew-avatar{height:32px;width:32px;border-radius:50%;background:#e8e9df;color:#62745e;display:grid;place-items:center}.crew-person b{font-size:11px}.crew-person small{display:block;font-size:9px;color:#8c9389;margin-top:3px}.crew-person>span:last-child{margin-left:auto;font:8px var(--mono);color:#85927d}.no-scroll{overflow:hidden}
@media(max-width:1100px){.game-layout{grid-template-columns:235px minmax(300px,1fr) 310px}.left-panel,.right-panel{padding-left:18px;padding-right:18px}.action-text b{font-size:9px}.action-text small{font-size:7px}.next-turn{padding:9px 8px}.next-turn small{font-size:7px}}
@media(max-width:800px){body{overflow:hidden}.game-shell{min-height:0}.topbar{height:55px;padding:0 16px}.brand{font-size:11px}.brand-mark{font-size:23px}.day-block{font-size:8px;gap:7px}.weather{padding-left:9px}.game-layout{height:calc(100dvh - 55px - 55px);display:block;position:relative}.map-stage{height:100%;width:100%}.left-panel,.right-panel{position:absolute;z-index:4;top:0;bottom:0;width:min(330px,88vw);background:#faf9f4f7;box-shadow:0 3px 20px #1f2c2340;transition:transform .25s;display:none}.left-panel{left:0;border-right:1px solid var(--line)}.right-panel{right:0;border-left:1px solid var(--line)}.game-layout.show-city .left-panel{display:block}.game-layout.show-actions .right-panel{display:block}.game-layout.show-crew .left-panel{display:block}.game-layout.show-ledger .right-panel{display:block}.mobile-nav{height:55px;position:fixed;z-index:6;left:0;right:0;bottom:0;display:flex;background:#fbfaf6;border-top:1px solid var(--line);padding-bottom:env(safe-area-inset-bottom);height:calc(55px + env(safe-area-inset-bottom));justify-content:space-around}.mobile-nav button{flex:1;border:0;background:none;color:#8d9389;font:8px var(--mono);letter-spacing:.4px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:2px}.mobile-nav button span{font-size:17px}.mobile-nav button.selected{color:#385544}.right-panel{max-height:100%;padding-top:23px}.left-panel{max-height:100%;padding-top:23px}.map-label{top:14px;left:12px;padding:7px 9px}.map-tools{top:13px;right:12px}.map-legend{left:10px;bottom:11px;gap:8px;padding:7px;font-size:6px}.map-hint{bottom:15px;right:10px;font-size:7px}.district-card{bottom:39px}.toast{bottom:calc(67px + env(safe-area-inset-bottom))}}
@media(max-width:430px){.day-block{font-size:7px;letter-spacing:.5px}.weather{font-size:0}.weather:first-letter{font-size:13px}.top-actions{gap:4px}.menu-btn{font-size:9px}.map-hint{max-width:100px;line-height:1.5;text-align:right}.map-legend{gap:6px}.map-legend span{gap:3px}.district-card{padding:15px}.district-card h2{font-size:22px}}

(() => {
  'use strict';
  const districts = [
    {id:'santa',name:'Santa Rosa',short:'SANTA ROSA',desc:'The old town. Everyone knows your name here.',status:'owned',income:1200,support:62,control:100,color:'#728d70',businesses:1,center:[0,0]},
    {id:'mercado',name:'El Mercado',short:'EL MERCADO',desc:'Busy market streets, full of small-business owners and big possibilities.',status:'open',income:1500,support:43,control:0,color:'#b4a77e',businesses:0,center:[1,0]},
    {id:'marina',name:'La Marina',short:'LA MARINA',desc:'A sunny waterfront strip with room for something special.',status:'open',income:1800,support:37,control:0,color:'#87a7a3',businesses:0,center:[2,0]},
    {id:'jardines',name:'Los Jardines',short:'LOS JARDINES',desc:'A leafy neighborhood where reputation matters most.',status:'open',income:1300,support:48,control:0,color:'#8fa17a',businesses:0,center:[0,1]},
    {id:'centro',name:'El Centro',short:'EL CENTRO',desc:'The city's beating heart. Everyone has a stake in it.',status:'rival',income:2400,support:27,control:0,color:'#a77e70',businesses:0,center:[1,1]},
    {id:'altura',name:'Las Alturas',short:'LAS ALTURAS',desc:'Hilltop homes and a view over the whole city.',status:'rival',income:2100,support:32,control:0,color:'#9d8ca5',businesses:0,center:[2,1]}
  ];
  const state={day:1,cash:12400,influence:18,heat:12,level:1,selected:0,sound:true,crew:2,log:[],zoom:1,panX:0,panY:0};
  const canvas=document.getElementById('cityCanvas'),ctx=canvas.getContext('2d');
  const $=id=>document.getElementById(id);let W=0,H=0,dpr=1,toastTimer,drag=null,scene=null;
  const names=['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'];
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
  function seeded(i,j){let n=(i+1)*127+(j+1)*43;return (Math.sin(n*12.9898)*43758.5453)%1+.5}
  function geometry(){let tw=Math.min(W*.225,H*.255)*state.zoom,th=tw*.49;const cx=W*.5+state.panX,cy=H*.49+state.panY;return districts.map(d=>({x:cx+(d.center[0]-1)*tw*.91+(d.center[1]===1?tw*.42:-tw*.42),y:cy+(d.center[1]-.5)*th*1.72+(d.center[0]===2?th*.05:0),tw,th}))}
  function poly(points,fill,stroke,line=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=line;ctx.strokeStyle=stroke;ctx.stroke()}}
  function diamond(x,y,tw,th,fill,stroke){poly([[x,y-th],[x+tw,y],[x,y+th],[x-tw,y]],fill,stroke,1)}
  function drawBuilding(x,y,w,h,depth,color,highlight,shade){ctx.beginPath();ctx.moveTo(x,y-h);ctx.lineTo(x+w,y-h-depth*.52);ctx.lineTo(x+w,y-depth*.52);ctx.lineTo(x,y);ctx.closePath();ctx.fillStyle=shade;ctx.fill();ctx.beginPath();ctx.moveTo(x,y-h);ctx.lineTo(x-w,y-h-depth*.52);ctx.lineTo(x-w,y-depth*.52);ctx.lineTo(x,y);ctx.closePath();ctx.fillStyle=color;ctx.fill();poly([[x,y-h],[x+w,y-h-depth*.52],[x,y-h-depth],[x-w,y-h-depth*.52]],highlight,'#46544755',.7);ctx.fillStyle='#f0dfac99';ctx.fillRect(x-w*.48,y-h-depth*.43,Math.max(2,w*.13),Math.max(2,h*.2));ctx.fillRect(x+w*.12,y-h-depth*.39,Math.max(2,w*.12),Math.max(2,h*.18))}
  function drawTree(x,y,s){ctx.fillStyle='#35584436';ctx.beginPath();ctx.ellipse(x,y+3,s*1.2,s*.6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#765d42';ctx.fillRect(x-1,y-s*.45,2,s*.55);ctx.fillStyle=['#617f5f','#758d65','#53775e'][Math.floor(seeded(Math.round(x),Math.round(y))*3)];ctx.beginPath();ctx.ellipse(x,y-s*.65,s*.58,s*.67,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a0af7a88';ctx.beginPath();ctx.ellipse(x-s*.15,y-s*.85,s*.24,s*.25,0,0,Math.PI*2);ctx.fill()}
  function drawTile(d,i,g){let {x,y,tw,th}=g;const selected=i===state.selected;let base=d.status==='owned'?'#d2d7bd':d.status==='rival'?'#d4c8bd':'#d7d4c3';
    // Neighborhood ground, block grid and quiet streets.
    diamond(x,y+6,tw,th, '#283a3130');diamond(x,y,tw,th,base,selected?'#f5e6b6':'#f8f6e8');
    ctx.save();ctx.beginPath();ctx.moveTo(x,y-th);ctx.lineTo(x+tw,y);ctx.lineTo(x,y+th);ctx.lineTo(x-tw,y);ctx.closePath();ctx.clip();
    const road='#e8e4d1',roadEdge='#b7b7a3';ctx.strokeStyle=roadEdge;ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(x-tw*.85,y-th*.38);ctx.lineTo(x+tw*.83,y+th*.39);ctx.moveTo(x-tw*.82,y+th*.39);ctx.lineTo(x+tw*.82,y-th*.39);ctx.stroke();ctx.strokeStyle=road;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x-tw*.85,y-th*.38);ctx.lineTo(x+tw*.83,y+th*.39);ctx.moveTo(x-tw*.82,y+th*.39);ctx.lineTo(x+tw*.82,y-th*.39);ctx.stroke();
    for(let b=0;b<12;b++){let rx=(seeded(i,b)*1.45-.725)*tw,ry=(seeded(b,i+9)*1.1-.55)*th;let u=(rx/tw)+(ry/th),v=(rx/tw)-(ry/th);if(Math.abs(u)>.77||Math.abs(v)>.73)continue;let px=x+rx,py=y+ry;let nearRoad=Math.min(Math.abs(ry/tw-.23*rx/tw),Math.abs(ry/tw+.23*rx/tw));if(nearRoad<.105)continue;
      if(b%5===0){drawTree(px,py,Math.min(tw*.075,7));continue}let size=tw*(.075+seeded(b+4,i)*.035),bh=th*(.08+seeded(b+1,i+5)*.11),dep=size*.45;let colors=[['#b28e69','#c9aa7a','#856f59'],['#9b9272','#c3b38b','#796f5c'],['#a37d72','#c79e88','#82675e'],['#85927a','#b0b38b','#66745f']][(i+b)%4];drawBuilding(px,py,size,bh,dep,colors[0],colors[1],colors[2]);
    }
    ctx.restore();
    // Small plaza/park and gentle district tint.
    if(i===3){poly([[x-tw*.39,y],[x,y-th*.19],[x+tw*.38,y],[x,y+th*.18]],'#9bb48a','#879f7a');drawTree(x-tw*.1,y,tw*.07);drawTree(x+tw*.13,y+th*.03,tw*.06)}
    if(i===2){diamond(x+tw*.42,y-th*.33,tw*.15,th*.08,'#9cc4c1','#769f9d')}
    if(d.status==='owned'){ctx.fillStyle='#4a674f';ctx.beginPath();ctx.arc(x-tw*.64,y-th*.25,3.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#eff1dd';ctx.font='8px "DM Mono"';ctx.textAlign='center';ctx.fillText('✦',x-tw*.64,y-th*.25+2.5)}
