  }
  function draw(){if(!ctx||!W||!H)return;ctx.clearRect(0,0,W,H);let grad=ctx.createLinearGradient(0,0,W,H);grad.addColorStop(0,'#d9ddd0');grad.addColorStop(.55,'#cbd4c4');grad.addColorStop(1,'#d7d0bc');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
