  function render(){ $('dayLabel').textContent=names[(state.day-1)%7]+' · DAY '+String(state.day).padStart(2,'0');$('feedDay').textContent='DAY '+String(state.day).padStart(2,'0');$('cash').textContent='$'+state.cash.toLocaleString();$('influence').innerHTML=state.influence+' <small>/ 100</small>';$('heat').innerHTML=state.heat+' <small>/ 100</small>';$('heatBar').style.width=state.heat+'%';$('level').textContent=state.level;renderSidebar();draw()}
  function notify(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
  function addEvent(title,text,type=''){const e=document.createElement('div');e.className='feed-event';e.innerHTML=`<span class="feed-dot ${type}"></span><div><b>${title}</b><p>${text}</p><small>DAY ${String(state.day).padStart(2,'0')}</small></div>`;$('eventFeed').prepend(e);while($('eventFeed').children.length>6)$('eventFeed').lastElementChild.remove()}
  function action(kind){const acts={community:{cost:2000,run(){state.influence=Math.min(100,state.influence+8);districts[state.selected].support=Math.min(95,districts[state.selected].support+5);state.heat=Math.max(0,state.heat-1);return ['A little goes a long way','Your neighborhood noticed the investment. Trust is growing.']}},business:{cost:4000,run(){districts[state.selected].businesses++;state.influence=Math.min(100,state.influence+3);return ['A new chapter','Your local business is open. It will bring in $650 each day.']}},network:{cost:3000,run(){state.crew++;state.influence=Math.min(100,state.influence+7);return ['A trusted new ally','Your circle is growing. Influence is easier to build together.']}},laylow:{cost:0,run(){state.heat=Math.max(0,state.heat-13);return ['A quieter day','You kept things low-key. The city's attention has moved elsewhere.']}};const a=acts[kind];if(!a)return;if(state.cash<a.cost){notify('Not enough cash for that move.');return}if(kind==='business'&&districts[state.selected].status!=='owned'){notify('Choose one of your neighborhoods first.');return}state.cash-=a.cost;const [title,text]=a.run();state.level=1+Math.floor(state.influence/30);addEvent(title,text,kind==='laylow'?'':'gold');notify(text);render()}
  function claim(){const d=districts[state.selected];if(d.status==='owned'){action('business');return}if(d.status==='rival'){if(state.influence<35){notify('Build your influence to 35 before approaching this neighborhood.');return}if(state.cash<6000){notify('You need $6,000 to make a proper introduction.');return}state.cash-=6000;d.status='owned';d.support=45;d.control=100;state.influence=Math.max(0,state.influence-8);state.heat=Math.min(100,state.heat+6);addEvent('A new chapter in '+d.name,'People are ready for a change. Your community work paid off.','gold');notify(d.name+' is now part of your network.')}else{const cost=d.income>2000?6000:3500;if(state.cash<cost||state.influence<20){notify('You need $'+cost+' and 20 influence to build a foothold.');return}state.cash-=cost;d.status='owned';d.support=Math.min(80,d.support+18);d.control=100;state.influence=Math.min(100,state.influence+5);state.heat=Math.min(100,state.heat+3);addEvent('A warm welcome in '+d.name,'Local leaders are open to working together.','gold');notify(d.name+' is now part of your network.')}render();setSelected(state.selected,true)}
