  document.querySelectorAll('.action-card').forEach(b=>b.onclick=()=>action(b.dataset.action));
  $('zoomIn').onclick=()=>{state.zoom=Math.min(1.35,state.zoom+.1);$('zoomLabel').textContent=Math.round(state.zoom*100)+'%';draw()};$('zoomOut').onclick=()=>{state.zoom=Math.max(.7,state.zoom-.1);$('zoomLabel').textContent=Math.round(state.zoom*100)+'%';draw()};$('centerMap').onclick=()=>{state.panX=state.panY=0;state.zoom=1;$('zoomLabel').textContent='100%';draw()};
  $('soundBtn').onclick=()=>{state.sound=!state.sound;$('soundBtn').style.opacity=state.sound?'1':'.45';notify(state.sound?'Sound enabled':'Sound muted')};
